function friendlyHttp(status,d,isJson,path){const ref=d?.requestId?` Reference: ${String(d.requestId).slice(0,80)}.`:'';if(native()&&!API)return `${APK_NO_API} Check the app configuration and retry.`;if(status===401)return `Your session is missing or expired. Sign in again.${ref}`;if(status===402)return `This action needs a Premium plan. Open Billing to upgrade.${ref}`;if(status===403){const why=String(d?.error||'').trim();return why&&isJson?`${why}${d?.code?` (${String(d.code).slice(0,40)})`:''}${ref}`:`This action is not available for the current account or connection. Check linked accounts and permissions.${ref}`}if(status===404&&isJson&&d?.error&&d.code!=='POTHUB_ROUTE_NOT_FOUND'&&d.error!=='Route not found')return `${d.error}${ref}`;if(status===404||status===405)return `This feature is unavailable in the current service version. Update PotHub or retry after deployment.${ref}`;if(status===413)return `This item is too large for this operation. Attach it through the large-file upload flow or split it into smaller parts.${ref}`;if(status===422)return `${d?.error||d?.message||'PotHub rejected the request format.'}${ref}`;if(status===429)return d?.code==='daily_limit_reached'&&d?.error?String(d.error):`PotHub is still busy after retrying. Try again in about ${Math.min(60,Math.max(5,Number(d?.retryAfter)||10))} seconds.${ref}`;if(status>=500)return `PotHub encountered a server problem. Retry once; if it continues, share the diagnostic reference with support.${ref}`;if(status>=400&&status<500&&isJson&&d?.error)return `${String(d.error).slice(0,300)}${d?.code&&!/^HTTP_/.test(String(d.code))?` (${String(d.code).slice(0,40)})`:''}${ref}`;return `PotHub could not complete that action (HTTP ${status}).${ref}`;}
