const withTimeout=(promise,ms,label)=>{try{window.__pothubBoot=label}catch{}let timer;return Promise.race([Promise.resolve(promise),new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${label} did not respond within ${Math.round(ms/1000)} seconds`)),ms)})]).finally(()=>clearTimeout(timer))};
async function api(path,opts={}){const {timeoutMs:requestTimeout=25000,noRetry=false,idempotencyKey,signal:externalSignal,...fetchOptions}=opts,method=String(fetchOptions.method||'GET').toUpperCase(),retryable=!noRetry&&(['GET','HEAD'].includes(method)||!!idempotencyKey);let attempt=0,sessionRefreshed=false,rateWaits=0;while(true){const ctrl=new AbortController(),t=setTimeout(()=>ctrl.abort(),requestTimeout);try{const headers={'Content-Type':'application/json',...((nativeSessionToken||webSessionToken)?{Authorization:`Bearer ${nativeSessionToken||webSessionToken}`}:{}),...(fetchOptions.headers||{})};if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const signal=externalSignal?(typeof AbortSignal.any==='function'?AbortSignal.any([ctrl.signal,externalSignal]):externalSignal):ctrl.signal;const r=await fetch(`${API}${path}`,{credentials:'include',...fetchOptions,headers,signal});const isJson=(r.headers.get('content-type')||'').includes('application/json');const d=isJson?await r.json().catch(()=>({})):{};if(r.status===401&&!sessionRefreshed&&firebaseSessionActive&&firebaseAuth?.currentUser&&path!=='/api/auth/firebase-exchange'){sessionRefreshed=true;webSessionToken='';try{await exchangeFirebaseSession(firebaseAuth.currentUser);continue}catch{}}if(r.status===429&&rateWaits<2&&!externalSignal?.aborted&&!['daily_limit_reached','AUTH_RATE_LIMITED'].includes(d?.code)){rateWaits++;await new Promise(x=>setTimeout(x,rateWaitMs(r.headers.get('retry-after'),d?.retryAfter,rateWaits)));continue}if(!r.ok)throw Object.assign(new Error(friendlyHttp(r.status,d,isJson,path)),{status:r.status,retryAfter:d?.retryAfter,code:d.code||`HTTP_${r.status}`,requestId:d.requestId||r.headers.get('x-request-id')||null,resetsAt:d.resetsAt,limit:d.limit,scope:d.scope||''});return d;}catch(e){if(idempotencyKey&&RESUMABLE_PATH.test(path)){const kind=pauseKindFor(e,{signal:externalSignal});if(kind){await waitForResume(kind,{signal:externalSignal,resetsAt:e.resetsAt,probe:healthProbe});continue}}if(retryable&&attempt<1&&(!e.status||e.status>=500)){await new Promise(r=>setTimeout(r,180));attempt++;continue}if(e.status)throw e;throw Object.assign(new Error(friendlyNetwork(e,path,requestTimeout)),{code:e.name==='AbortError'?'TIMEOUT':'NETWORK'})}finally{clearTimeout(t)}}}

