    if(response.status===200||response.status===201){offset=file.size;finished=true}
    else if(response.status===308){const range=response.headers.get('Range')||'';const match=range.match(/bytes=0-(\d+)/i);offset=match?Math.min(file.size,Number(match[1])+1):end;attempt=0}
