const hinted=hint&&pool.length>1?routeByMention(pool,hint):null;if(hinted?.matched)return hinted.agents;const pins=await getPickedAgents();const pinned=(backendOnly?rows.filter(isBackendAgent):rows).find(a=>String(a.id)===String(pins[fn]));if(pinned)return [pinned];
