async function diagnose(rescue=false){if(!repo)return showError(new Error('Choose a repository first.'));if(!logs.trim())return showError(new Error('Paste failing logs or error output first.'));const ags=await functionAgents('Diagnosis');if(!ags.length){setAgentFn('Diagnosis');setSection('agents');return showError(new Error('No Diagnosis agent is configured. Add or enable one in API & Agents.'))}const controller=new AbortController();activeCreatorChatController=controller;activeCreatorChatId=chatId;setBusy('diagnosis');setError('');try{const headers=ags.length?await agentHeadersForFunction(ags,'diagnosis'):null,operationId=uid();const d=await api('/api/diagnose',{method:'POST',timeoutMs:52000,idempotencyKey:operationId,signal:controller.signal,headers:headers?.headers||{},body:JSON.stringify({operationId,agentIds:headers?.agentIds||[],repo:{owner:repo.owner.login,name:repo.name,defaultBranch:repo.default_branch},logs,...(headers?.agentConfig?{agentConfig:headers.agentConfig}:{})})});setDiagnosis(d);if(Number.isFinite(d.creditsRemaining))setCredits(d.creditsRemaining);await saveRun({kind:'diagnosis',repo:repo.full_name,result:d});setAiFallbackOpen(false);setPendingAiOperation('');}catch(e){if(e?.name!=='AbortError'&&!controller.signal.aborted){if(!rescue&&/temporarily unavailable|all configured ai routes failed|ai fallback|provider.*failed/i.test(String(e?.message||''))){setPendingAiOperation('diagnosis');setAiFallbackOpen(true);setError('')}else showError(e)}}finally{if(activeCreatorChatController===controller){activeCreatorChatController=null;activeCreatorChatId=null}setBusy('')}}
