async function promptCommit(){return askText('Commit changes','Enter a commit message.','Fix issues identified by Pothub','Continue')}
async function saveRun(x){const row={id:uid(),...x,createdAt:new Date().toISOString(),status:'complete'};await db.runs.put(row);setHistory(await db.runs.orderBy('createdAt').reverse().limit(30).toArray());queueCloudSync()}
