async function openChat(id){const loadGeneration=++chatLoadGeneration.current;activeChatIdRef.current=id;try{if(activeCreatorChatController&&activeCreatorChatId!==id){activeCreatorChatController.abort();activeCreatorChatController=null;activeCreatorChatId=null}setEditingMessageId(null);const rows=await db.messages.where('chatId').equals(id).sortBy('createdAt');if(loadGeneration!==chatLoadGeneration.current)return;setChatId(id);setMessages(rows);setMobileHistory(false)}catch(e){showError(e)}}
